mapper.select:
SELECT  FROM fit_training_plan WHERE tenant_id = #{tenantId}
AND member_id = #{memberId}
ORDER BY create_time DESC, plan_id DESC LIMIT 200

mapper.update:
UPDATE fit_training_plan SET name = #{plan.name}, description = #{plan.description}, visibility = #{plan.visibility},
    cycle_days = #{plan.cycleDays}, days_json = #{plan.daysJson}, version = version + 1, update_time = NOW()
WHERE tenant_id = #{plan.tenantId} AND plan_id = #{plan.planId}

mapper.select:
SELECT * FROM fit_training_audit WHERE tenant_id = #{tenantId}
AND plan_id = #{planId}
ORDER BY create_time DESC, audit_id DESC LIMIT 500

SELECT p.plan_id, p.member_id, p.visibility FROM fit_training_media_ref r
JOIN fit_training_plan p ON p.plan_id = r.plan_id AND p.tenant_id = r.tenant_id
WHERE r.tenant_id = #{tenantId} AND r.asset_id = #{assetId}
